 */
public object FfiConverterTypeEncryptorDecryptor: FfiConverter<EncryptorDecryptor, Long> {
    internal val handleMap = UniffiHandleMap<EncryptorDecryptor>()

    override fun lower(value: EncryptorDecryptor): Long {
        if (value is EncryptorDecryptorImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): EncryptorDecryptor {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return EncryptorDecryptorImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): EncryptorDecryptor {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: EncryptorDecryptor) = 8UL

    override fun write(value: EncryptorDecryptor, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


