/**
 * @suppress
 */
public object FfiConverterTypeKeyManager: FfiConverter<KeyManager, Long> {
    internal val handleMap = UniffiHandleMap<KeyManager>()

    override fun lower(value: KeyManager): Long {
        if (value is KeyManagerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): KeyManager {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return KeyManagerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): KeyManager {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: KeyManager) = 8UL

    override fun write(value: KeyManager, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


