    /**
     * Returns a bridged sync engine for Desktop's Sync framework.
     * Without this UDL entry the engine is invisible to JS: UniFFI generates
     * the XPCOM glue that lets JS call `rustStore.bridgedEngine()`.
     */
    fun `bridgedEngine`(): LoginsBridgedEngine
    
    fun `count`(): kotlin.Long
    
    fun `countByFormActionOrigin`(`formActionOrigin`: kotlin.String): kotlin.Long
    
    fun `countByOrigin`(`origin`: kotlin.String): kotlin.Long
    
    fun `delete`(`id`: kotlin.String): kotlin.Boolean
    
    /**
     * Delete all logins. Returns the ids of the deleted logins.
     */
    fun `deleteAll`(): List<kotlin.String>
    
    /**
     * Delete all logins except the FxA session-credentials login. Returns the
     * ids of the deleted logins.
     */
    fun `deleteAllExceptFxa`(): List<kotlin.String>
    
    fun `deleteMany`(`ids`: List<kotlin.String>): List<kotlin.Boolean>
    
    /**
     * The `delete_undecryptable_records_for_remote_replacement` function locally deletes stored logins
     * that cannot be decrypted and sets the last sync time to 0 so any existing server records can be downloaded
     * and overwrite the locally deleted records.
     *
     * NB: This function was created to unblock iOS logins users who are unable to sync logins and should not be used
     * outside of this use case.
     */
    fun `deleteUndecryptableRecordsForRemoteReplacement`(): LoginsDeletionMetrics
    
    fun `findLoginToUpdate`(`look`: LoginEntry): Login?
    
    fun `get`(`id`: kotlin.String): Login?
    
    fun `getByBaseDomain`(`baseDomain`: kotlin.String): List<Login>
    
    fun `hasLoginsByBaseDomain`(`baseDomain`: kotlin.String): kotlin.Boolean
    
    fun `isEmpty`(): kotlin.Boolean
    
    /**
     * Checks if a login's password matches any password in the local breach database.
     *
     * Returns true if this login's password appears in the breachesL table, indicating
     * that the same password has been breached on a different domain (password reuse).
     * This is independent of whether this specific login has been marked as breached.
     */
    fun `isPotentiallyVulnerablePassword`(`id`: kotlin.String): kotlin.Boolean
    
    fun `list`(): List<Login>
    
    /**
     * Stores that the user dismissed the breach alert for a login.
     */
    fun `recordBreachAlertDismissal`(`id`: kotlin.String)
    
    /**
     * Stores the time at which the user dismissed the breach alert for a login.
     */
    fun `recordBreachAlertDismissalTime`(`id`: kotlin.String, `timestamp`: kotlin.Long)
    
    /**
     * Records a list of potentially vulnerable passwords in the breach database.
     *
     * This is used to bulk-populate the breachesL table with known breached passwords,
     * typically during import operations or when syncing breach data.
     * Passwords are encrypted before storage and duplicates are automatically filtered out.
     */
    fun `recordPotentiallyVulnerablePasswords`(`passwords`: List<kotlin.String>)
    
    fun `registerWithSyncManager`()
    
    fun `reset`()
    
    /**
     * Removes all recorded breaches.
     */
    fun `resetAllBreaches`()
    
    /**
     * Run maintenance on the DB
     *
     * This is intended to be run during idle time and will take steps / to clean up / shrink the
     * database.
     */
    fun `runMaintenance`(`options`: RunMaintenanceOptions? = null)
    
    fun `shutdown`()
    
    fun `touch`(`id`: kotlin.String)
    
    fun `update`(`id`: kotlin.String, `login`: LoginEntry): Login
    
    /**
     * Clear out locally stored logins data
